mapper.select:
SELECT id, tunnel_id AS tunnelId, stat_date AS statDate, warn_total AS warnTotal, warn_red AS warnRed, warn_confirmed AS warnConfirmed, warn_closed AS warnClosed, dispose_total AS disposeTotal, dispose_closed AS disposeClosed, patrol_total AS patrolTotal, patrol_done AS patrolDone, hazard_new AS hazardNew, hazard_closed AS hazardClosed, sample_count AS sampleCount, sample_expect AS sampleExpect FROM rpt_stat_daily WHERE stat_date BETWEEN #{from} AND #{to}
AND tunnel_id = #{tunnelId}
AND 1=0
AND ${scope.column} IN #{p}
ORDER BY stat_date
